ndcg.pseudocode:
def dcg(rels, k):
    # 순위 i(1부터)의 관련도를 log2(i+1)로 할인
    return sum(rel / log2(i + 1)
               for i, rel in enumerate(rels[:k], start=1))

def ndcg(ranked_rels, k):
    # 이상 순위: 관련도 내림차순 정렬 (최대 DCG)
    ideal = sorted(ranked_rels, reverse=True)
    idcg = dcg(ideal, k)
    return dcg(ranked_rels, k) / idcg if idcg > 0 else 0.0

# 관련도 [3, 2, 3, 0, 1]
# DCG ≈ 6.149, IDCG ≈ 6.323 → nDCG@5 ≈ 0.972
